import { AskContext, Harness, HarnessReply } from "@amykit/core";
import { NamedHarness } from "./collection.js";
import { HandoffLog, handoffNote, recordHandoff, recordSkillHandoff } from "./handoff.js";
import { nextRung } from "./ladder.js";
import { Ladders, everyRung, rungsFor } from "./ladders.js";

/** Which skills answer for a step, in the order they are tried. */
export type SkillLadders = Readonly<Record<string, readonly string[]>>;

export interface HarnessRelayDeps extends HandoffLog {
  skills?: SkillLadders;
  /**
   * Where a skill named in a ladder is installed: the directory holding its
   * `SKILL.md`. A harness that runs apart from the operator's own setup is
   * handed that directory, since it would not find the skill otherwise.
   */
  locate?: (skill: string) => string | undefined;
}

/**
 * One harness made of several, with nobody's prompts in it.
 *
 * The same two ladders the ticket-shaped relay climbs, over the same rungs,
 * for the same reasons: the skill ladder is who should do the step, the
 * harness ladder is what to do when the one asked ran out of quota or was not
 * up to it. What is missing here is any notion of what the step *is* — a
 * caller hands over a prompt and a directory, and gets back an answer and an
 * account of what it cost.
 *
 * That is the whole difference between a harness plugin one workflow can use
 * and a harness plugin any workflow can.
 */
export class HarnessRelay implements Harness {
  readonly name = "relay";

  constructor(
    private readonly ladders: Ladders<NamedHarness>,
    private readonly deps: HarnessRelayDeps = {},
  ) {
    if (everyRung(ladders).length === 0) {
      throw new Error("the relay has no harness to relay to: no harness plugin contributed one");
    }
  }

  /**
   * Hands the question to each skill named for the step, until one answers.
   *
   * With no skill configured this is one turn on the caller's own prompt,
   * which is every install that has not asked for anything else.
   */
  async ask(prompt: string, cwd: string, context: AskContext = {}): Promise<HarnessReply> {
    const skills = (context.step && this.deps.skills?.[context.step]) || [];
    if (skills.length === 0) return this.climb(prompt, cwd, context, undefined);

    let last: HarnessReply | null = null;

    for (let index = 0; index < skills.length; index += 1) {
      const skill = skills[index]!;
      last = await this.climb(prompt, cwd, context, skill);

      if (last.run.outcome === "completed") return last;

      // `abandoned` stops here for the same reason it stops the harness
      // ladder: it is what a killed child looks like, and the handbrake has
      // to mean the next thing does not start.
      const next = skills[index + 1];
      if (!next || last.run.outcome === "abandoned") break;

      recordSkillHandoff(this.deps, context.workId, step(context), skill, next, last.run);
    }

    return last!;
  }

  /**
   * Walks the harness ladder until something answers, or until the policy
   * says there is nowhere left to go.
   *
   * The reply that comes back is the last one attempted, so a caller sees a
   * real outcome rather than a summary of several.
   */
  private async climb(
    prompt: string,
    cwd: string,
    context: AskContext,
    skill: string | undefined,
  ): Promise<HarnessReply> {
    // Chosen once per climb rather than per rung: a step that swapped ladders
    // half way up would make "the next rung" mean nothing.
    const ladder = rungsFor(this.ladders, context.step);

    let index = 0;
    let handoff: string | undefined;
    let last: HarnessReply | null = null;
    const handed = withSkill(context, skill, this.deps.locate);

    while (index < ladder.length) {
      const rung = ladder[index]!;
      last = await rung.cli.ask(asked(prompt, skill, handoff), cwd, handed);
      // The caller says whether a completed run holds while there is still a
      // rung to climb to, rather than after the ladder has stopped.
      if (last.run.outcome === "completed" && context.verify) last = await context.verify(last);

      const next = nextRung(ladder, index, last.run.outcome);
      if (next === null) return last;

      const to = ladder[next]!;
      recordHandoff(this.deps, context.workId, step(context), rung, to, last.run);
      handoff = handoffNote(rung, last.run);
      index = next;
    }

    // Unreachable while the ladder is non-empty, and the constructor refuses
    // an empty one.
    return last!;
  }
}

/**
 * The prompt as it is actually sent: addressed to a skill when one was named,
 * and carrying what the previous rung left behind.
 */
function asked(prompt: string, skill: string | undefined, handoff: string | undefined): string {
  const body = handoff ? `${prompt}\n\n${handoff}` : prompt;
  return skill ? `/${skill}\n\n${body}` : body;
}

/**
 * The context a rung is asked with: the caller's, plus the skill the prompt
 * is addressed to and where it lives, when the relay knows.
 */
function withSkill(
  context: AskContext,
  skill: string | undefined,
  locate: ((skill: string) => string | undefined) | undefined,
): AskContext {
  const path = skill ? locate?.(skill) : undefined;
  return skill && path ? { ...context, skill: { name: skill, path } } : context;
}

/** What the log calls the step, for a caller that did not say. */
function step(context: AskContext): string {
  return context.step ?? "ask";
}

import { Harness } from "@amykit/core";
import { Rung } from "./ladder.js";

/**
 * The collection every harness plugin adds its CLI to, one per model tier.
 *
 * A harness plugin contributes rather than mounting the `agent` port: only
 * one plugin can own a port, and three harnesses that each wanted to be *the*
 * agent would refuse to mount together. The relay composes what is
 * contributed, and a single-harness install goes through the same relay.
 *
 * `harness` and `model` are declared rather than discovered, because the
 * relay has to decide **where to go next** before running anything: a quota
 * problem wants a different harness and a failure wants a stronger model.
 */
export const HARNESS_COLLECTION = "harness";

/** One rung of the ladder: a harness at one model, with nobody's prompts on it. */
export interface NamedHarness extends Rung {
  readonly cli: Harness;
}

import { AgentRun, EventLog } from "@amykit/core";
import { Rung } from "./ladder.js";

export interface HandoffLog {
  log?: EventLog;
  now?: () => Date;
}

/**
 * What the next harness is told about the one before it.
 *
 * The working tree is left exactly as the harness that gave up left it, so
 * the next one is told it is picking up half-done work. Resetting would throw
 * away whatever was already right, and on a long piece of work that is
 * expensive enough to risk hitting the same quota again.
 */
export function handoffNote(from: Rung, run: AgentRun): string {
  const because =
    run.outcome === "rate-limited"
      ? `ran out of quota partway through`
      : `did not succeed`;

  return [
    `A previous attempt by ${from.harness} (${from.model}) ${because}.`,
    `The working tree is exactly as it left it, so this may be half-done work`,
    `rather than a clean start. Continue it; do not begin again.`,
    ...(run.output ? [``, `What it said:`, ``, run.output] : []),
  ].join("\n");
}

/** Says which rung gave up and which one is being asked next. */
export function recordHandoff(
  deps: HandoffLog,
  workId: string | undefined,
  action: string,
  from: Rung,
  to: Rung,
  run: AgentRun,
): void {
  append(deps, workId, {
    action,
    cause: run.outcome,
    from: { harness: from.harness, model: from.model },
    to: { harness: to.harness, model: to.model },
    // Which axis moved, which is what a report about reliability wants.
    moved: from.harness === to.harness ? "model" : "harness",
  });
}

/**
 * The same event as a harness handoff, because it is the same question with a
 * third axis: `moved` already answers "what changed".
 */
export function recordSkillHandoff(
  deps: HandoffLog,
  workId: string | undefined,
  action: string,
  from: string,
  to: string,
  run: AgentRun,
): void {
  append(deps, workId, {
    action,
    cause: run.outcome,
    from: { skill: from },
    to: { skill: to },
    moved: "skill",
  });
}

function append(deps: HandoffLog, workId: string | undefined, detail: Record<string, unknown>): void {
  deps.log?.append({
    at: (deps.now ?? (() => new Date()))().toISOString(),
    kind: "agent.handoff",
    ...(workId === undefined ? {} : { workId }),
    detail,
  });
}

