/**
 * Pulls the first JSON object out of a model's answer.
 *
 * An agent asked for JSON will usually oblige, and will sometimes wrap it in
 * a fenced block or a sentence. Scanning for the first balanced object is
 * more forgiving than trusting the whole reply to parse, and still fails
 * loudly when there is no object at all.
 */
export function extractJson<T>(text: string): T {
  const start = text.indexOf("{");
  if (start === -1) {
    throw new Error(`no JSON object in the reply: ${preview(text)}`);
  }

  let depth = 0;
  let inString = false;
  let escaped = false;

  for (let index = start; index < text.length; index += 1) {
    const character = text[index];

    if (escaped) {
      escaped = false;
      continue;
    }
    if (character === "\\") {
      escaped = true;
      continue;
    }
    if (character === '"') {
      inString = !inString;
      continue;
    }
    if (inString) continue;

    if (character === "{") depth += 1;
    if (character === "}") {
      depth -= 1;
      if (depth === 0) {
        return JSON.parse(text.slice(start, index + 1)) as T;
      }
    }
  }

  throw new Error(`the JSON object in the reply is not closed: ${preview(text)}`);
}

function preview(text: string): string {
  const trimmed = text.trim();
  return trimmed.length > 200 ? `${trimmed.slice(0, 200)}...` : trimmed;
}

import { AgentOutcome } from "@amykit/core";

export interface Rung {
  readonly name: string;
  readonly harness: string;
  readonly model: string;
  /**
   * This rung's runs arrive with a cost on them without the price table
   * being consulted.
   *
   * Declared by the harness plugin, because only it knows how its CLI
   * accounts: claude puts `total_cost_usd` in its envelope, and hermes
   * writes `cost_status: "included"` for a model that ran locally, where
   * zero is the right answer and no row in any price table would ever
   * exist. codex has the table and nothing else.
   *
   * Read by whoever asks whether a ceiling in money could stop anything.
   * Without it that question collapses into "is this model in the table",
   * which is a different question with the same answer only for codex —
   * and refusing an install whose costs arrive reported is the same failure
   * as an inert ceiling, arrived at from the other side.
   */
  readonly pricesItsOwnRuns?: boolean;
}

/**
 * Where to go after a rung did not work out, or nowhere.
 *
 * The two causes want opposite moves, which is the whole reason this is not a
 * plain retry loop:
 *
 * - **rate-limited** is not a capability problem. A stronger model on the
 *   same harness is still behind the same quota, so every remaining rung of
 *   that harness is skipped and the next harness gets it.
 * - **failed** might be a capability problem, so the next rung is tried in
 *   order: the next model of the same harness first, and only once those run
 *   out, the next harness. That is how both axes get exhausted rather than
 *   one.
 * - **abandoned** stops the ladder. A missing binary is one cause and
 *   `amy stop` killing the child is another, and retrying the second would
 *   start a fresh child the moment the handbrake came down. `amy doctor`
 *   is what catches the missing binary, before a ticket is touched.
 * - **completed** never asks.
 */
export function nextRung(
  ladder: readonly Rung[],
  current: number,
  outcome: AgentOutcome,
): number | null {
  if (outcome === "completed" || outcome === "abandoned") return null;

  const here = ladder[current];
  if (!here) return null;

  for (let index = current + 1; index < ladder.length; index += 1) {
    const rung = ladder[index]!;
    if (outcome === "rate-limited" && rung.harness === here.harness) continue;
    return index;
  }

  return null;
}

import { Rung } from "./ladder.js";

/**
 * Which rungs answer for a step, and which answer for everything else.
 *
 * One ladder for the whole install is the right default and the wrong ceiling.
 * Reading a ticket to decide whether it is clear enough to start is not the
 * same job as writing the change, and putting both behind one list means
 * paying the expensive model to do the cheap step, or asking the cheap one to
 * do the work.
 *
 * So the ladder is per step, with a default, and the step is the action's own
 * name — which the relay already had in hand for choosing a skill. That is
 * also what makes routing by difficulty possible without anything here
 * learning the word: a workflow that triages into easy and hard emits
 * different actions for each, and the config points them at different rungs.
 */
export interface Ladders<T extends Rung> {
  /** Used by any step that names no ladder of its own. */
  readonly fallback: readonly T[];
  readonly byStep: Readonly<Record<string, readonly T[]>>;
}

/** One ladder for everything, which is what an install starts with. */
export function oneLadder<T extends Rung>(rungs: readonly T[]): Ladders<T> {
  return { fallback: rungs, byStep: {} };
}

/**
 * The rungs for a step, or the fallback.
 *
 * A step with an empty ladder falls back rather than failing: an operator who
 * writes `triage: []` has said nothing about triage, and the alternative is a
 * relay with nowhere to go, which the constructor already refuses to be.
 */
export function rungsFor<T extends Rung>(ladders: Ladders<T>, step?: string): readonly T[] {
  const named = step ? ladders.byStep[step] : undefined;
  return named && named.length > 0 ? named : ladders.fallback;
}

/** Every rung any step could reach, for a caller that has to check them all. */
export function everyRung<T extends Rung>(ladders: Ladders<T>): readonly T[] {
  return [...ladders.fallback, ...Object.values(ladders.byStep).flat()];
}

import { Agent, AgentResult, AskContext, AttemptOutcome, HarnessReply } from "@amykit/core";
import { extractJson } from "./json.js";

/** One question to the agent, in the directory the work is in. */
export interface StepInput {
  prompt: string;
  cwd: string;
  context?: AskContext;
}

export interface ImplementInput extends StepInput {
  /**
   * Commits what the agent left behind, and says whether there was anything.
   *
   * The caller's, because when work is committed and when it reaches the
   * remote are the workflow's decisions: one pushes after every attempt,
   * another once per cycle. This helper never names git.
   */
  commit: () => Promise<boolean>;
  /** The progress key a retry is judged by. */
  key?: string;
  now?: () => Date;
}

const NO_CHANGE = "the agent finished without changing any file";

/**
 * Asks for a change, commits it through the caller, and says whether it moved.
 *
 * The commit runs as the context's `verify`, so a relay commits after each
 * rung that completed and climbs on one that changed nothing, exactly as it
 * climbs on a failure. Over an agent that never calls `verify` the commit
 * runs once the answer is back. A run that completed and changed no file is
 * a failure with `unchanged` progress, so a retry policy can tell an attempt
 * that added nothing from one that did. A run that did not complete is
 * returned rather than thrown, with its account.
 */
export async function implementStep(agent: Agent, input: ImplementInput): Promise<AgentResult<AttemptOutcome>> {
  // The last run `verify` judged, and whether it changed anything. Only the
  // run that comes back is the attempt's, so an earlier rung's verdict never
  // speaks for a later rung that failed for another reason.
  let judged: { reply: HarnessReply; changed: boolean } | undefined;
  const verify = async (reply: HarnessReply): Promise<HarnessReply> => {
    const changed = await input.commit();
    const verdict = changed ? reply : { ...reply, run: { ...reply.run, outcome: "failed" as const, output: `${NO_CHANGE}\n\n${reply.run.output}` } };
    judged = { reply: verdict, changed };
    return verdict;
  };

  let reply = await agent.ask(input.prompt, input.cwd, { ...input.context, verify });
  if (reply.run.outcome === "completed" && judged?.reply !== reply) reply = await verify(reply);

  const at = (input.now ?? (() => new Date()))().toISOString();
  const key = input.key ?? "implementation";

  if (judged?.reply === reply && !judged.changed) {
    return {
      value: { ok: false, output: reply.run.output, at, progress: { kind: "unchanged", key, detail: NO_CHANGE } },
      run: reply.run,
    };
  }
  if (reply.run.outcome !== "completed") {
    return { value: { ok: false, output: reply.run.output, at }, run: reply.run };
  }
  return { value: { ok: true, output: reply.run.output, at, progress: { kind: "advanced", key } }, run: reply.run };
}

export interface JudgeInput<T> extends StepInput {
  /** Turns the JSON object the prompt asked for into the step's answer. */
  read: (answer: unknown) => T;
  /** The answer when the run did not complete, so there is nothing to read. */
  fallback: T;
}

/**
 * Asks a question whose answer is one JSON object, and reads it.
 *
 * A run that did not complete yields the caller's fallback with the run's
 * account, for the same reason `implementStep` returns rather than throws.
 */
export async function judgeStep<T>(agent: Agent, input: JudgeInput<T>): Promise<AgentResult<T>> {
  const reply = await agent.ask(input.prompt, input.cwd, input.context);
  if (reply.run.outcome !== "completed") return { value: input.fallback, run: reply.run };
  return { value: input.read(extractJson<unknown>(reply.text)), run: reply.run };
}

import { Harness, Registry } from "@amykit/core";
import { HARNESS_COLLECTION, NamedHarness } from "./collection.js";

export interface TierOptions {
  /** The harness name, which is also the axis the relay swaps along. */
  harness: string;
  /**
   * The model tiers, cheapest first. Empty means one agent on whatever model
   * the harness defaults to, which is the single-model install.
   */
  models: readonly string[];
  make: (model: string) => Harness;
  /** See `Rung.pricesItsOwnRuns`. Declared once per harness, not per tier. */
  pricesItsOwnRuns?: boolean;
}

/**
 * Adds one harness per model tier to the collection the relay reads.
 *
 * The naming lives here rather than in each harness plugin because it is a
 * contract: the ladder in a config file refers to these names, so three
 * plugins inventing three conventions would make the config unlearnable.
 */
export function contributeTiers(registry: Registry, opts: TierOptions): NamedHarness[] {
  // The union the config sent can name a model twice — `ladder` and a step's
  // own both saying `claude:opus` is the shape `amy init` ships. A rung is a
  // name in a collection here, and a second contribution under a name already
  // present is refused at boot. Dedupe, keeping the first mention: a ladder
  // is ordered, and the first mention is the one that means something.
  const seen = new Set<string>();
  const models = opts.models.filter((model) => {
    const key = `${model}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
  if (models.length === 0) models.push("");

  return models.map((model) => {
    const named: NamedHarness = {
      name: tierName(opts.harness, model),
      harness: opts.harness,
      model,
      pricesItsOwnRuns: opts.pricesItsOwnRuns ?? false,
      cli: opts.make(model),
    };
    registry.contribute(HARNESS_COLLECTION, named.name, named);
    return named;
  });
}

/** `claude:opus`, or plain `claude` when no model was named. */
export function tierName(harness: string, model: string): string {
  return model ? `${harness}:${model}` : harness;
}

import { Registry } from "@amykit/core";

/** One provider-reported period of subscription usage. */
export interface UsageWindow {
  readonly label: string;
  readonly usedPercent: number;
  readonly startsAt?: string;
  readonly resetsAt?: string;
}

/** A usage answer the provider documents or otherwise offers. */
export interface UsageAvailable {
  readonly windows: readonly UsageWindow[];
  readonly unofficial?: boolean;
}

/** A provider whose usage answer could not be read at this moment. */
export interface UsageUnavailable {
  readonly unavailable: string;
}

export type UsageResult = UsageAvailable | UsageUnavailable;

/** A harness's on-demand view of one subscription's usage. */
export interface UsageReader {
  readonly label: string;
  read(): Promise<UsageResult>;
}

/** The collection harness plugins add usage readers to. */
export const USAGE_COLLECTION = "usage";

/** Adds one harness usage reader for a host to read on demand. */
export function contributeUsage(registry: Registry, reader: UsageReader): void {
  registry.contribute(USAGE_COLLECTION, reader.label, reader);
}
